CREATE TABLE "control"."access_audit" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"actor" text NOT NULL,
	"workspace_id" text NOT NULL,
	"environment" text,
	"form_id" text,
	"kind" text NOT NULL,
	"occurred_at" timestamp with time zone DEFAULT now() NOT NULL,
	"detail" text,
	CONSTRAINT "access_audit_kind" CHECK ("control"."access_audit"."kind" in ('read', 'export', 'erasure', 'grant', 'revoke', 'setting'))
);
